import * as ui from "std/ui"

@jsonable
class LogEntry {
  personName: string;
  birthday: number;
  minute: number;
}

@jsonable
class AppState {
  reminderLeadDays: number;
  entries: LogEntry[];
  draft_personName: string;
  draft_birthday: number;
  removedEntries: LogEntry[];
  removedAt: number;
  settingsOpen: boolean;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {reminderLeadDays: 1, entries: emptyEntries, draft_personName: "", draft_birthday: time.daysSinceEpoch(), removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_reminderLeadDays(state: AppState, value: number): AppState {
  return {reminderLeadDays: value, entries: state.entries, draft_personName: state.draft_personName, draft_birthday: state.draft_birthday, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_personName(state: AppState, value: string): AppState {
  return {draft_personName: value, reminderLeadDays: state.reminderLeadDays, entries: state.entries, draft_birthday: state.draft_birthday, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function set_draft_birthday(state: AppState, value: number): AppState {
  return {draft_birthday: value, reminderLeadDays: state.reminderLeadDays, entries: state.entries, draft_personName: state.draft_personName, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_personName) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {personName: strings.trim(state.draft_personName), birthday: state.draft_birthday, minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_personName: "", reminderLeadDays: state.reminderLeadDays, draft_birthday: state.draft_birthday, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, reminderLeadDays: state.reminderLeadDays, draft_personName: state.draft_personName, draft_birthday: state.draft_birthday, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, reminderLeadDays: state.reminderLeadDays, draft_personName: state.draft_personName, draft_birthday: state.draft_birthday, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
  return {removedEntries: none, removedAt: -1, reminderLeadDays: state.reminderLeadDays, entries: state.entries, draft_personName: state.draft_personName, draft_birthday: state.draft_birthday, settingsOpen: state.settingsOpen};
}





function toggleSettings(state: AppState, ignored: number): AppState {
  return {settingsOpen: !state.settingsOpen, reminderLeadDays: state.reminderLeadDays, entries: state.entries, draft_personName: state.draft_personName, draft_birthday: state.draft_birthday, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Birthday Reminders", "BIRTHDAYS", "Keep every birthday and get a calendar reminder", ""));
  {
      let reminderLeadDays: number = state.reminderLeadDays;
      let reminderHour: number = 540;
      let entryCount: number = state.entries.length();
      let entryTotal: number = 0;
    let rows: ui.View[] = [];
    let i: number = entryCount - 1;
    while (i >= 0 && i > entryCount - 21) {
      let e: LogEntry = state.entries[i];
      let sub: string = ui.dateToString(e.birthday) + " · " + "Added " + ui.clockToString(e.minute);
      rows.push(ui.ListItem("default", e.personName, sub, "", "", 0, false, ""));
      rows.push(ui.ActionBar("end", [ui.Button("secondary", "Remove", "removeEntry", i, true)]));
      i = i - 1;
    }
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Name", state.draft_personName, "set_draft_personName"), ui.DateField("default", "Birthday", state.draft_birthday, "set_draft_birthday"), ui.ActionBar("end", [ui.Button("primary", "Add", "addEntry", 0, strings.trim(state.draft_personName) !== "")])]));
    sections.push(ui.Section("content", "", "", [ui.SectionHeader("default", "Birthdays", "Newest first", ui.numberToString(entryCount)), ui.When(entryCount === 0, ui.EmptyState("default", "Nothing added yet", "Fill in the fields above and tap Add.", "", "", "list")), ui.When(entryCount > 0, ui.ListGroup("default", "", rows)), ui.When(state.removedEntries.length() > 0, ui.Snackbar("default", "Removed", "Undo", "undoRemove")), ui.Ticker("default", "undoClock", 6000 + state.entries.length() % 7, state.removedEntries.length() > 0, "expireUndo")]));
  }
  {
    let settingsWord: string = "Show";
    if (state.settingsOpen) { settingsWord = "Hide"; }
    sections.push(ui.Section("supporting", "", "", [
      ui.ListItem("default", "Settings", "1 setting", settingsWord, "toggleSettings", 0, true, ""),
      ui.When(state.settingsOpen, ui.Column("default", [ui.NumberField("default", "Remind me before (days)", state.reminderLeadDays, 0, 30, "set_reminderLeadDays")]))
    ]));
  }
  return ui.AppTheme("clean", "", sections);
}

