import * as ui from "std/ui"

@jsonable
class AppState {
  elapsedMs: number;
  running: boolean;
  finished: boolean;
  startLengthIndex: number;
}

function init(): AppState {
  return {elapsedMs: 0, running: false, finished: false, startLengthIndex: 2};
}

function countdownSeconds(state: AppState): number {
  let startLengthValues: number[] = [3, 5, 10, 15];
  let startLength: number = startLengthValues[state.startLengthIndex];
  let beepInterval: number = 1;
  return startLength;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, startLengthIndex: state.startLengthIndex}; }
  return {elapsedMs: total, running: false, finished: true, startLengthIndex: state.startLengthIndex};
}

function onStart(state: AppState, ignored: number): AppState {
  let startAt: number = state.elapsedMs;
  if (state.finished) { startAt = 0; }
  return {running: true, finished: false, elapsedMs: startAt, startLengthIndex: state.startLengthIndex};
}

function onStop(state: AppState, ignored: number): AppState {
  return {running: false, elapsedMs: state.elapsedMs, finished: state.finished, startLengthIndex: state.startLengthIndex};
}

function onReset(state: AppState, ignored: number): AppState {
  return {running: false, finished: false, elapsedMs: 0, startLengthIndex: state.startLengthIndex};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_startLength(state: AppState, value: number): AppState {
  return {startLengthIndex: value, elapsedMs: 0, running: false, finished: false};
}







