    sections.push(ui.Section("hero", "", "", [ui.Hero("accent", "Race start countdown", ui.durationToString(math.ceil(remaining)), "", [ui.ActionBar("spread", [ui.Button("primary", "Start", "onStart", 0, !state.running), ui.Button("secondary", "Stop", "onStop", 0, state.running), ui.Button("secondary", "Reset", "onReset", 0, true)])])]));
