import * as ui from "std/ui"

@jsonable
class AppState {
  elapsedMs: number;
  running: boolean;
  finished: boolean;
  callLengthIndex: number;
}

function init(): AppState {
  return {elapsedMs: 0, running: false, finished: false, callLengthIndex: 1};
}

function countdownSeconds(state: AppState): number {
  let callLengthValues: number[] = [5, 10, 15, 30];
  let callLength: number = callLengthValues[state.callLengthIndex];
  return callLength * 60;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, callLengthIndex: state.callLengthIndex}; }
  return {elapsedMs: total, running: false, finished: true, callLengthIndex: state.callLengthIndex};
}

function onStart(state: AppState, ignored: number): AppState {
  let startAt: number = state.elapsedMs;
  if (state.finished) { startAt = 0; }
  return {running: true, finished: false, elapsedMs: startAt, callLengthIndex: state.callLengthIndex};
}

function onStop(state: AppState, ignored: number): AppState {
  return {running: false, elapsedMs: state.elapsedMs, finished: state.finished, callLengthIndex: state.callLengthIndex};
}

function onReset(state: AppState, ignored: number): AppState {
  return {running: false, finished: false, elapsedMs: 0, callLengthIndex: state.callLengthIndex};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_callLength(state: AppState, value: number): AppState {
  return {callLengthIndex: value, elapsedMs: 0, running: false, finished: false};
}







