import * as ui from "std/ui"

@jsonable
class AppState {
  elapsedMs: number;
  running: boolean;
  finished: boolean;
  countdownLengthIndex: number;
}

function init(): AppState {
  return {elapsedMs: 0, running: false, finished: false, countdownLengthIndex: 1};
}

function countdownSeconds(state: AppState): number {
  let countdownLengthValues: number[] = [0, 3, 5, 10];
  let countdownLength: number = countdownLengthValues[state.countdownLengthIndex];
  return countdownLength;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, countdownLengthIndex: state.countdownLengthIndex}; }
  return {elapsedMs: total, running: false, finished: true, countdownLengthIndex: state.countdownLengthIndex};
}

function onStart(state: AppState, ignored: number): AppState {
  let startAt: number = state.elapsedMs;
  if (state.finished) { startAt = 0; }
  return {running: true, finished: false, elapsedMs: startAt, countdownLengthIndex: state.countdownLengthIndex};
}

function onStop(state: AppState, ignored: number): AppState {
  return {running: false, elapsedMs: state.elapsedMs, finished: state.finished, countdownLengthIndex: state.countdownLengthIndex};
}

function onReset(state: AppState, ignored: number): AppState {
  return {running: false, finished: false, elapsedMs: 0, countdownLengthIndex: state.countdownLengthIndex};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_countdownLength(state: AppState, value: number): AppState {
  return {countdownLengthIndex: value, elapsedMs: 0, running: false, finished: false};
}







function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Silly Face Camera Roll", "SILLY FACES", "Snap goofy faces and keep them in a roll", "clock"));
  {
    sections.push(ui.Ticker("default", "clock", 200, state.running, "onTick"));
      let countdownLengthValues: number[] = [0, 3, 5, 10];
      let countdownLength: number = countdownLengthValues[state.countdownLengthIndex];
      let duration: number = countdownSeconds(state);
      let elapsed: number = math.min(state.elapsedMs / 1000, duration);
      let remaining: number = duration - elapsed;
    sections.push(ui.Section("hero", "", "", [ui.Hero("accent", "Face timer", ui.durationToString(math.ceil(remaining)), "", [ui.ActionBar("spread", [ui.Button("primary", "Start", "onStart", 0, !state.running), ui.Button("secondary", "Stop", "onStop", 0, state.running), ui.Button("secondary", "Reset", "onReset", 0, true)])])]));
    sections.push(ui.Section("content", "", "", [ui.Select("default", "Countdown", ["Off", "3 seconds", "5 seconds", "10 seconds"], state.countdownLengthIndex, "set_countdownLength")]));
  }
  return ui.AppTheme("playful", "", sections);
}

