}

function countdownSeconds(state: AppState): number {
  let inhaleSeconds: number = state.inhaleSeconds;
  let holdSeconds: number = state.holdSeconds;
  let exhaleSeconds: number = state.exhaleSeconds;
  let cueTone: number = 440;
  let cycleSeconds: number = ((inhaleSeconds + holdSeconds) + exhaleSeconds);
  return cycleSeconds;
}

function onTick(state: AppState, elapsedMs: number): AppState {
  if (!state.running) { return state; }
  let total: number = countdownSeconds(state) * 1000;
  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, inhaleSeconds: state.inhaleSeconds, holdSeconds: state.holdSeconds, exhaleSeconds: state.exhaleSeconds, soundOn: state.soundOn, settingsOpen: state.settingsOpen}; }
