  let inhaleMs: number = state.inhaleSeconds * 1000;
  let holdMs: number = state.holdSeconds * 1000;
  let exhaleMs: number = state.exhaleSeconds * 1000;
  let cycleMs: number = inhaleMs + holdMs + exhaleMs;
  if (cycleMs <= 0) { return 0; }
  let pos: number = elapsedMs % cycleMs;
  if (pos < inhaleMs) { return 0; }
  if (pos < inhaleMs + holdMs) { return 1; }
  return 2;
